import { defineFunction, fail } from "@relkit/app/functions";
import { z } from "@relkit/app/schema";
import Rejected from "../errors/rejected.error.js";
import { membershipRejection } from "../rules.js";

const role = z.union([z.literal("owner"), z.literal("admin"), z.literal("dispatcher"), z.literal("driver")]);

export default defineFunction({
  id: "companies.add-membership",
  input: z.object({
    companyId: z.string().min(1),
    userId: z.string().min(1),
    role,
    existingUserIds: z.array(z.string().min(1)),
  }),
  output: z.object({ companyId: z.string(), userId: z.string(), role, status: z.literal("active") }),
  errors: [Rejected],
  handler: async ({ existingUserIds, ...membership }) => {
    const reason = membershipRejection(membership.userId, existingUserIds);
    if (reason !== null) return fail(Rejected, { reason });
    return { ...membership, status: "active" as const };
  },
});

