    if (reason !== null) return fail(Rejected, { reason });
    return { ...company, status: "active" as const };
  },
});

src/services/companies/rules.ts.content:
export function onboardingRejection(slug: string, existingSlugs: readonly string[]): string | null {
  return existingSlugs.includes(slug) ? "Company slug already exists" : null;
}

export function membershipRejection(userId: string, existingUserIds: readonly string[]): string | null {
  return existingUserIds.includes(userId) ? "User is already a company member" : null;
}

