src/services/fleet/rules.ts.content:
export function carRejection(input: {
  companyId: string;
  modelCompanyId: string;
  plate: string;
  existingPlates: readonly string[];
}): string | null {
  if (input.companyId !== input.modelCompanyId) return "Car model belongs to another company";
  if (input.existingPlates.includes(input.plate)) return "Plate already exists in this company";
  return null;
}

export function driverRejection(input: {
  licenseNumber: string;
  existingLicenseNumbers: readonly string[];
  licenseExpiresAtMs: number;
  nowMs: number;
}): string | null {
  if (input.licenseExpiresAtMs <= input.nowMs) return "Driver license has expired";
  if (input.existingLicenseNumbers.includes(input.licenseNumber)) return "License already exists in this company";
  return null;
}

