import { defineFunction, fail } from "@relkit/app/functions";
import { z } from "@relkit/app/schema";
import Rejected from "../errors/rejected.error.js";
import { positionRejection } from "../rules.js";

export default defineFunction({
  id: "tracking.accept-position",
  input: z.object({
    companyId: z.string().min(1),
    car: z.object({
      carId: z.string().min(1), companyId: z.string().min(1),
      latestRecordedAtMs: z.number().int().nonnegative().nullable(),
    }),
    latitude: z.number().min(-90).max(90),
    longitude: z.number().min(-180).max(180),
    recordedAtMs: z.number().int().nonnegative(), nowMs: z.number().int().nonnegative(),
  }),
  output: z.object({
    companyId: z.string(), carId: z.string(), latitude: z.number(),
    longitude: z.number(), recordedAtMs: z.number(),
  }),
  errors: [Rejected],
  handler: async (input) => {
    const reason = positionRejection(input);
    if (reason !== null) return fail(Rejected, { reason });
    const { car, nowMs: _nowMs, ...position } = input;
    return { ...position, carId: car.carId };
  },
});

src/services/tracking/rules.ts.content:
export const MAX_POSITION_AGE_MS = 120_000;

export function positionRejection(input: {
  companyId: string;
  car: { companyId: string; latestRecordedAtMs: number | null };
  latitude: number;
  longitude: number;
  recordedAtMs: number;
  nowMs: number;
}): string | null {
  if (input.companyId !== input.car.companyId) return "Car belongs to another company";
  if (!Number.isFinite(input.latitude) || Math.abs(input.latitude) > 90) return "Latitude is out of range";
  if (!Number.isFinite(input.longitude) || Math.abs(input.longitude) > 180) return "Longitude is out of range";
  if (input.recordedAtMs > input.nowMs) return "GPS position is in the future";
  if (input.nowMs - input.recordedAtMs > MAX_POSITION_AGE_MS) return "GPS position is stale";
  if (input.car.latestRecordedAtMs !== null && input.recordedAtMs <= input.car.latestRecordedAtMs) {
    return "GPS position must be newer than the previous position";
  }
  return null;
}

