import { defineFunction, fail } from "@relkit/app/functions";
import { z } from "@relkit/app/schema";
import Rejected from "../errors/rejected.error.js";
import { assignmentRejection } from "../rules.js";
import { tripSnapshot } from "../schemas.js";

export default defineFunction({
  id: "trips.assign-trip",
  input: z.object({
    companyId: z.string().min(1), trip: tripSnapshot,
    nowMs: z.number().int().nonnegative(),
    car: z.object({
      carId: z.string().min(1), companyId: z.string().min(1),
      status: z.union([z.literal("available"), z.literal("reserved"), z.literal("maintenance")]),
    }),
    driver: z.object({
      driverId: z.string().min(1), companyId: z.string().min(1),
      status: z.union([z.literal("active"), z.literal("inactive")]), reserved: z.boolean(),
      licenseExpiresAtMs: z.number().int().nonnegative(),
    }),
  }),
  output: z.object({
    companyId: z.string(), tripId: z.string(), carId: z.string(),
    driverId: z.string(), status: z.literal("assigned"),
  }),
  errors: [Rejected],
  handler: async (input) => {
    const reason = assignmentRejection(input);
    if (reason !== null) return fail(Rejected, { reason });
    return {
      companyId: input.companyId, tripId: input.trip.tripId,
      carId: input.car.carId, driverId: input.driver.driverId, status: "assigned" as const,
    };
  },
});

