import { defineFunction, fail } from "@relkit/app/functions";
import { z } from "@relkit/app/schema";
import Rejected from "../errors/rejected.error.js";
import { transitionRejection } from "../rules.js";
import { tripSnapshot, tripStatus } from "../schemas.js";

export default defineFunction({
  id: "trips.transition-trip",
  input: z.object({ companyId: z.string().min(1), trip: tripSnapshot, nextStatus: tripStatus }),
  output: tripSnapshot,
  errors: [Rejected],
  handler: async ({ companyId, trip, nextStatus }) => {
    if (trip.companyId !== companyId) return fail(Rejected, { reason: "Trip belongs to another company" });
    const reason = transitionRejection(trip.status, nextStatus);
    if (reason !== null) return fail(Rejected, { reason });
    return { ...trip, status: nextStatus };
  },
});

src/services/trips/rules.ts.content:
export const tripStatuses = ["draft", "assigned", "in_progress", "completed", "cancelled"] as const;
export type TripStatus = (typeof tripStatuses)[number];

export function assignmentRejection(input: {
  companyId: string;
  trip: { companyId: string; status: TripStatus };
  car: { companyId: string; status: "available" | "reserved" | "maintenance" };
  driver: {
    companyId: string;
    status: "active" | "inactive";
    reserved: boolean;
    licenseExpiresAtMs: number;
  };
  nowMs: number;
}): string | null {
  if ([input.trip, input.car, input.driver].some((entity) => entity.companyId !== input.companyId)) {
    return "Assignment resources must belong to the trip company";
  }
  if (input.trip.status !== "draft") return "Only a draft trip can be assigned";
  if (input.car.status !== "available") return "Car is unavailable";
  if (input.driver.status !== "active" || input.driver.reserved) return "Driver is unavailable";
  if (input.driver.licenseExpiresAtMs <= input.nowMs) return "Driver license has expired";
  return null;
}

const transitions: Readonly<Record<TripStatus, readonly TripStatus[]>> = {
  draft: ["cancelled"],
  assigned: ["in_progress", "cancelled"],
  in_progress: ["completed"],
  completed: [],
  cancelled: [],
};

export function transitionRejection(current: TripStatus, next: TripStatus): string | null {
  return transitions[current].includes(next) ? null : `Cannot transition trip from ${current} to ${next}`;
}

