import { expect, test } from "bun:test";
import { invokeFunction } from "@relkit/testing";
import companies from "@app/services/companies/service.js";
import fleet from "@app/services/fleet/service.js";
import trips from "@app/services/trips/service.js";
import maintenance from "@app/services/maintenance/service.js";
import tracking from "@app/services/tracking/service.js";

test("companies exposes validated onboarding and memberships", async () => {
  const company = { companyId: "c1", name: " Fleet ", slug: " FLEET ", existingSlugs: [] };
  await expect(invokeFunction(companies.onboardCompany, company)).resolves.toEqual({
    companyId: "c1", name: "Fleet", slug: "fleet", status: "active",
  });
  await expect(invokeFunction(companies.onboardCompany, { ...company, existingSlugs: ["fleet"] })).rejects.toThrow("Company slug already exists");
  const membership = { companyId: "c1", userId: "u1", role: "dispatcher" as const, existingUserIds: [] };
  await expect(invokeFunction(companies.addMembership, membership)).resolves.toEqual({
    companyId: "c1", userId: "u1", role: "dispatcher", status: "active",
  });
  await expect(invokeFunction(companies.addMembership, { ...membership, existingUserIds: ["u1"] })).rejects.toThrow("already a company member");
  await expect(invokeFunction(companies.addMembership, { ...membership, role: "root" } as never)).rejects.toThrow();
  await expect(invokeFunction(companies.onboardCompany, { ...company, name: " " })).rejects.toThrow();
});

test("fleet exposes validated models, cars and drivers", async () => {
  const model = { companyId: "c1", modelId: "m1", manufacturer: "Toyota", name: "Hiace", seats: 12 };
  await expect(invokeFunction(fleet.registerModel, model)).resolves.toEqual(model);
  await expect(invokeFunction(fleet.registerModel, { ...model, seats: 0 })).rejects.toThrow();
  const car = {
    companyId: "c1", carId: "car1", model: { companyId: "c1", modelId: "m1" },
    plate: " abc ", odometerKm: 100, existingPlates: [],
  };
  await expect(invokeFunction(fleet.registerCar, car)).resolves.toEqual({
