  });
  await expect(invokeFunction(fleet.registerCar, { ...car, existingPlates: ["ABC"] })).rejects.toThrow("Plate already exists");
  await expect(invokeFunction(fleet.registerCar, { ...car, model: { ...car.model, companyId: "c2" } })).rejects.toThrow("another company");
  const driver = {
