test("trips validates assignment and transitions through its public service", async () => {
  await expect(invokeFunction(trips.assignTrip, assignment)).resolves.toEqual({
    companyId: "c1", tripId: "t1", carId: "car1", driverId: "d1", status: "assigned",
  });
  await expect(invokeFunction(trips.assignTrip, { ...assignment, car: { ...assignment.car, status: "reserved" } })).rejects.toThrow("Car is unavailable");
  await expect(invokeFunction(trips.assignTrip, { ...assignment, driver: { ...assignment.driver, companyId: "c2" } })).rejects.toThrow("trip company");
  const transition = { companyId: "c1", trip: { ...assignment.trip, status: "assigned" as const }, nextStatus: "in_progress" as const };
  await expect(invokeFunction(trips.transitionTrip, transition)).resolves.toMatchObject({ tripId: "t1", status: "in_progress" });
  await expect(invokeFunction(trips.transitionTrip, { ...transition, nextStatus: "completed" })).rejects.toThrow("Cannot transition");
  await expect(invokeFunction(trips.transitionTrip, { ...transition, companyId: "c2" })).rejects.toThrow("another company");
  await expect(invokeFunction(trips.transitionTrip, { ...transition, nextStatus: "unknown" } as never)).rejects.toThrow();
});

test("maintenance validates the odometer at the public operation", async () => {
  const input = {
    companyId: "c1", maintenanceId: "m1", car: { carId: "car1", companyId: "c1", odometerKm: 100 },
    odometerKm: 100, description: "Oil change", performedAtMs: 100,
  };
  await expect(invokeFunction(maintenance.recordMaintenance, input)).resolves.toEqual({
    companyId: "c1", maintenanceId: "m1", carId: "car1", odometerKm: 100, description: "Oil change", performedAtMs: 100,
  });
  await expect(invokeFunction(maintenance.recordMaintenance, { ...input, odometerKm: 99 })).rejects.toThrow("cannot decrease");
  await expect(invokeFunction(maintenance.recordMaintenance, { ...input, odometerKm: -1 })).rejects.toThrow();
  await expect(invokeFunction(maintenance.recordMaintenance, { ...input, companyId: "c2" })).rejects.toThrow("another company");
