test("tracking validates coordinates, freshness and point ordering publicly", async () => {
  const input = {
    companyId: "c1", car: { carId: "car1", companyId: "c1", latestRecordedAtMs: null },
    latitude: 90, longitude: -180, recordedAtMs: 80_000, nowMs: 200_000,
  };
  await expect(invokeFunction(tracking.acceptPosition, input)).resolves.toEqual({
    companyId: "c1", carId: "car1", latitude: 90, longitude: -180, recordedAtMs: 80_000,
  });
  for (const latitude of [90.001, -90.001, NaN, Infinity]) {
    await expect(invokeFunction(tracking.acceptPosition, { ...input, latitude })).rejects.toThrow();
  }
  await expect(invokeFunction(tracking.acceptPosition, { ...input, longitude: 181 })).rejects.toThrow();
  await expect(invokeFunction(tracking.acceptPosition, { ...input, recordedAtMs: 79_999 })).rejects.toThrow("stale");
  await expect(invokeFunction(tracking.acceptPosition, { ...input, recordedAtMs: 200_001 })).rejects.toThrow("future");
  await expect(invokeFunction(tracking.acceptPosition, { ...input, car: { ...input.car, latestRecordedAtMs: 80_000 } })).rejects.toThrow("newer");
});

