import { expect, test } from "bun:test";
import { onboardingRejection, membershipRejection } from "../../src/services/companies/rules.js";
import { carRejection, driverRejection } from "../../src/services/fleet/rules.js";
import { assignmentRejection, transitionRejection, tripStatuses } from "../../src/services/trips/rules.js";
import { maintenanceRejection } from "../../src/services/maintenance/rules.js";
import { positionRejection } from "../../src/services/tracking/rules.js";

test("company onboarding and membership reject duplicates", () => {
  expect(onboardingRejection("fleet", [])).toBeNull();
  expect(onboardingRejection("fleet", ["fleet"])).not.toBeNull();
  expect(membershipRejection("user-1", [])).toBeNull();
  expect(membershipRejection("user-1", ["user-1"])).not.toBeNull();
});

test("fleet rejects cross-company model, duplicate plate, expired and duplicate licenses", () => {
  const car = { companyId: "c1", modelCompanyId: "c1", plate: "ABC", existingPlates: [] };
  expect(carRejection(car)).toBeNull();
  expect(carRejection({ ...car, modelCompanyId: "c2" })).not.toBeNull();
  expect(carRejection({ ...car, existingPlates: ["ABC"] })).not.toBeNull();
  const driver = { licenseNumber: "L1", existingLicenseNumbers: [], licenseExpiresAtMs: 101, nowMs: 100 };
  expect(driverRejection(driver)).toBeNull();
  expect(driverRejection({ ...driver, licenseExpiresAtMs: 100 })).not.toBeNull();
  expect(driverRejection({ ...driver, existingLicenseNumbers: ["L1"] })).not.toBeNull();
});

const assignment = {
  companyId: "c1", nowMs: 100,
  trip: { companyId: "c1", status: "draft" as const },
  car: { companyId: "c1", status: "available" as const },
  driver: { companyId: "c1", status: "active" as const, reserved: false, licenseExpiresAtMs: 101 },
};

test("assignment requires same company, draft trip, available car and eligible driver", () => {
  expect(assignmentRejection(assignment)).toBeNull();
  for (const entity of ["trip", "car", "driver"] as const) {
    expect(assignmentRejection({ ...assignment, [entity]: { ...assignment[entity], companyId: "c2" } })).not.toBeNull();
  }
  expect(assignmentRejection({ ...assignment, trip: { ...assignment.trip, status: "assigned" } })).not.toBeNull();
  for (const status of ["maintenance", "reserved"] as const) {
    expect(assignmentRejection({ ...assignment, car: { ...assignment.car, status } })).not.toBeNull();
  }
  expect(assignmentRejection({ ...assignment, driver: { ...assignment.driver, status: "inactive" } })).not.toBeNull();
  expect(assignmentRejection({ ...assignment, driver: { ...assignment.driver, reserved: true } })).not.toBeNull();
  expect(assignmentRejection({ ...assignment, driver: { ...assignment.driver, licenseExpiresAtMs: 100 } })).not.toBeNull();
});

const allowed = new Set(["draft:cancelled", "assigned:in_progress", "assigned:cancelled", "in_progress:completed"]);
for (const current of tripStatuses) {
  for (const next of tripStatuses) {
    test(`trip transition ${current} -> ${next}`, () => {
      expect(transitionRejection(current, next) === null).toBe(allowed.has(`${current}:${next}`));
    });
  }
}

test("maintenance rejects decreasing odometers and accepts equal or increased values", () => {
  const input = { companyId: "c1", car: { companyId: "c1", odometerKm: 100 }, odometerKm: 100 };
  expect(maintenanceRejection(input)).toBeNull();
  expect(maintenanceRejection({ ...input, odometerKm: 101 })).toBeNull();
  expect(maintenanceRejection({ ...input, odometerKm: 99 })).not.toBeNull();
  expect(maintenanceRejection({ ...input, companyId: "c2" })).not.toBeNull();
});

const position = {
  companyId: "c1", car: { companyId: "c1", latestRecordedAtMs: null },
  latitude: 0, longitude: 0, recordedAtMs: 200_000, nowMs: 200_000,
};

test("GPS accepts coordinate extremes and exact freshness threshold", () => {
  expect(positionRejection(position)).toBeNull();
  expect(positionRejection({ ...position, latitude: -90, longitude: 180, recordedAtMs: 80_000 })).toBeNull();
  expect(positionRejection({ ...position, latitude: 90, longitude: -180 })).toBeNull();
});

test("GPS rejects stale, future, repeated, out-of-order and foreign-company points", () => {
  expect(positionRejection({ ...position, recordedAtMs: 79_999 })).not.toBeNull();
  expect(positionRejection({ ...position, recordedAtMs: 200_001 })).not.toBeNull();
  for (const latestRecordedAtMs of [200_000, 200_001]) {
    expect(positionRejection({ ...position, car: { companyId: "c1", latestRecordedAtMs } })).not.toBeNull();
  }
  expect(positionRejection({ ...position, car: { companyId: "c1", latestRecordedAtMs: 199_999 } })).toBeNull();
  expect(positionRejection({ ...position, companyId: "c2" })).not.toBeNull();
});

for (const [latitude, longitude] of [[90.001, 0], [-90.001, 0], [0, 180.001], [0, -180.001], [NaN, 0], [0, Infinity]]) {
  test(`GPS rejects invalid coordinates ${latitude}, ${longitude}`, () => {
    expect(positionRejection({ ...position, latitude: latitude!, longitude: longitude! })).not.toBeNull();
  });
}
